    EnTextos.textMensaEaInfluenciaTempInteriorModoSinReferencia,
    "Dans cette influence 2 sections sont définies (référence, correction), vous affectez les entrées à corriger (ouvrir plus). Si la température de la section à corriger est supérieure (différentiel de température) à la section de référence, l'influence commencera à ouvrir progressivement l'entrée dans la section à corriger, jusqu'à la correction maximale si la condition reste vraie. Lorsque la condition devient fausse et que nous effectuons une correction, nous réduisons progressivement la correction."
